-- The two checklists published on 2026-11-14: Keeping a Journal You Actually
-- Return To (Journaling) and When You Might Lose Your Home (Housing).
-- Generated by `python3 tools/checklists_sql.py keeping-a-journal-you-actually-return-to
-- when-you-might-lose-your-home`; the repo copy in data/checklists.json is
-- the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('keeping-a-journal-you-actually-return-to', 'Keeping a Journal You Actually Return To', 'For a journal you keep starting and abandoning. It shrinks the entry to three lines, puts the notebook where you already sit, begins with what happened rather than how you felt, and lets a week of gaps be fine.', 'Journaling', '["Write three lines rather than three pages — a page you dread is a page you skip.", "Keep it where you already sit down — a notebook in a drawer is a notebook you forgot.", "Start with what happened, not how you felt — facts are easier to begin with than feelings.", "Date every entry — the dates are what make it useful to you in a year.", "Skip a week without starting over — a journal with gaps in it is still a journal.", "Write the sentence you would not say out loud — that is the one worth the paper.", "Read last month once — patterns show up in review and never in the moment.", "Keep it somewhere you trust — honesty needs to know nobody else is reading.", "Stop when you have said the thing — finishing early is how it stays something you want to do."]'::jsonb, 'daily', array['Habits', 'Mindfulness', 'Self-Compassion']::text[], 1, '2026-11-14T16:00:00+00:00'::timestamptz),
  ('when-you-might-lose-your-home', 'When You Might Lose Your Home', 'For when a notice has arrived and your housing is at risk. It reads the dates properly, gets you on the phone before the deadline, finds the help your county offers, puts the paperwork in one folder, and writes down where you could go.', 'Housing', '["Read the letter properly, all of it — the dates in it are the only real clock.", "Call the landlord or lender before the date — people negotiate far more often than they evict.", "Find out what help your county actually offers — emergency rent funds exist and go unclaimed.", "Get free advice before you sign anything — a housing counselor knows rules you will not find alone.", "Put every document in one folder — you will be asked for the same papers repeatedly.", "Tell one person you trust what is happening — shame keeps this secret far longer than it needs to be.", "Write down the three places you could go — a bad option written down beats a blank.", "Keep paying something if you can, and say so — a partial payment on record helps your case.", "Do one ordinary thing each day regardless — the whole day cannot be about this and hold."]'::jsonb, 'as needed', array['Money', 'Stress', 'Resilience']::text[], 1, '2026-11-14T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
